VAR
    Overload_Timer : TON;
END_VAR

Overload_Alarm := (Motor_Current > 51.9);

Overload_Timer(IN := Overload_Alarm AND Motor_Running, PT := T#30S);

IF Overload_Timer.Q THEN
    Motor_Stop := TRUE;
ELSIF Fault_Reset THEN
    Motor_Stop := FALSE;
END_IF;

